def sample_nam(names):
    # Filter out names that start with a lowercase letter
    filtered_names = [name for name in names if name[0].isupper()]
    # Calculate the sum of the lengths of the filtered names
    return sum(len(name) for name in filtered_names)

def check_integer(s):
    # Check if the string is empty
    if not s:
        return False
    # Check if the string is a valid integer
    try:
        int(s)
        return True
    except ValueError:
        return False

def count_divisors(n):
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count % 2 == 0

def tuple_str_int(tuple_str):
    # Remove the parentheses from the string
    tuple_str = tuple_str[1:-1]
    # Split the string by comma and convert each element to an integer
    return tuple(int(x) for x in tuple_str.split(','))

def jacobsthal_num(n):
    """
    Calculate the nth Jacobsthal number.

    Args:
    n (int): The position in the Jacobsthal sequence.

    Returns:
    int: The nth Jacobsthal number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return jacobsthal_num(n-1) + 2*jacobsthal_num(n-2)

def text_match_wordz_middle(text):
    # Check if the string contains 'z' at the start or end
    if text[0] == 'z' or text[-1] == 'z':
        return False
    # Check if 'z' is present in the middle of the string
    for i in range(1, len(text) - 1):
        if text[i] == 'z':
            return True
    return False

import re

def is_decimal(s):
    # Regular expression to match a decimal number with a precision of 2
    pattern = r'^\d+(\.\d{2})?$'
    return bool(re.match(pattern, s))

def check_greater(arr, num):
    # Iterate through each element in the array
    for element in arr:
        # Check if the current element is greater than the given number
        if element > num:
            # If found, return False
            return False
    # If no element is greater than the given number, return True
    return True

def right_insertion(arr, x):
    # Initialize the left and right pointers
    left, right = 0, len(arr) - 1

    # Perform binary search
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    # Return the right insertion point
    return left

def check_expression(expression):
    stack = []
    for char in expression:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack:
                return False
            top = stack.pop()
            if (char == ')' and top != '(') or (char == '}' and top != '{') or (char == ']' and top != '['):
                return False
    return not stack

