def even_position(lst):
    # Iterate through the list using a for loop
    for i in range(len(lst)):
        # Check if the index is even
        if i % 2 == 0:
            # Check if the number at the even index is even
            if lst[i] % 2 != 0:
                # If the number is odd, return False
                return False
    # If all even indices contain even numbers, return True
    return True

def max_run_uppercase(s):
    max_run = 0
    current_run = 0
    for char in s:
        if char.isupper():
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 0
    return max_run

def is_Sub_Array(arr1, arr2):
    # Check if the length of arr1 is greater than arr2
    if len(arr1) > len(arr2):
        return False
    # Iterate through arr1
    for i in range(len(arr1)):
        # Check if the current element of arr1 matches the first element of arr2
        if arr1[i] == arr2[0]:
            # Check if the remaining elements of arr1 match the remaining elements of arr2
            if arr1[i:i+len(arr2)] == arr2:
                return True
    return False
